interface VolumeCalculation {
    double calculateVolume(List<Shape> shapes);
}

public class VolumeCalculator implements VolumeCalculation {
    private List<Shape> shapes;
    public VolumeCalculator(List<Shape> shapes) {
        this.shapes = shapes;
    }
    @Override
    public double calculateVolume() {
        double totalVolume = 0;
        for (Shape shape : shapes) {
            if (shape instanceof HasVolume) {
                totalVolume += ((HasVolume) shape).volume();
            }
        }
        return totalVolume;
    }
}

